-- Generate images arrays from existing thumbnail URLs
UPDATE products SET images = jsonb_build_array(
  regexp_replace(image, 'thumbnail\\.webp$', '1.webp'),
  regexp_replace(image, 'thumbnail\\.webp$', '2.webp'),
  regexp_replace(image, 'thumbnail\\.webp$', '3.webp'),
  regexp_replace(image, 'thumbnail\\.webp$', '4.webp')
) WHERE images = '[]'::jsonb;
